update public.barangays b set boundary = coalesce((
  with filled as (select extensions.st_union(extensions.st_makepolygon(extensions.st_exteriorring(p.geom))) as g from extensions.st_dump(b.boundary) p),
  cut as (select (extensions.st_dump(extensions.st_difference(filled.g, far.g))).geom as geom from filled, far)
  select extensions.st_multi(extensions.st_collect(extensions.st_makepolygon(extensions.st_exteriorring(cut.geom)))) from cut
  where extensions.st_geometrytype(cut.geom) = 'ST_Polygon' and extensions.st_area(cut.geom::extensions.geography) > 30000
), b.boundary)
from far where extensions.st_intersects(b.boundary, far.g);
